```python
import openpyxl

def get_green_cells(file_path):
    wb = openpyxl.load_workbook(file_path)
    ws = wb.active
    greens = []
    for row in ws.iter_rows():
        for cell in row:
            fill = cell.fill
            if fill and fill.start_color:
                c = fill.start_color.rgb or fill.start_color.indexed
                # Accept common green variants
                green_rgbs = {"FF00FF00", "FF008000", "FF00FF99"}
                if isinstance(c, str) and c in green_rgbs:
                    greens.append((cell.row, cell.column))
    print(greens)

